if st.session_state.blown:
    # ===== لحن عيد ميلاد سعيد (مركّب، بلا ملف صوتي خارجي) =====
    components.html("""
    <script>
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      const ctx = new AudioCtx();
      // [تردد، مدة بالثانية]
      const notes = [
        [392.00,0.3],[392.00,0.3],[440.00,0.6],[392.00,0.6],[523.25,0.6],[493.88,1.1],
        [392.00,0.3],[392.00,0.3],[440.00,0.6],[392.00,0.6],[587.33,0.6],[523.25,1.1],
        [392.00,0.3],[392.00,0.3],[783.99,0.6],[659.25,0.6],[523.25,0.6],[493.88,0.6],[440.00,1.1],
        [698.46,0.3],[698.46,0.3],[659.25,0.6],[523.25,0.6],[587.33,0.6],[523.25,1.2]
      ];
      let t = ctx.currentTime + 0.05;
      notes.forEach(([freq,dur])=>{
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = "triangle";
        osc.frequency.value = freq;
        gain.gain.setValueAtTime(0.0001, t);
        gain.gain.exponentialRampToValueAtTime(0.25, t+0.03);
        gain.gain.exponentialRampToValueAtTime(0.0001, t+dur*0.9);
        osc.connect(gain).connect(ctx.destination);
        osc.start(t);
        osc.stop(t+dur);
        t += dur*0.95;
      });
    } catch(e) { console.log("audio blocked", e); }
    </script>
    """, height=0)

    # ===== تفجير الكونفيتي =====
    colors = ["#c9457e", "#e3ac47", "#8fadb0", "#eaa898", "#f2d17a", "#ffffff"]
    shapes = ["50%", "2px", "50% 0 50% 0"]
    pieces = []
    for i in range(70):
        left = random.uniform(0, 100)
        size = random.uniform(6, 12)
        color = random.choice(colors)
        shape = random.choice(shapes)
        duration = random.uniform(2.2, 3.6)
        delay = random.uniform(0, 0.6)
        drift = random.uniform(-90, 90)
        spin = random.choice([360, -360, 540, -540])
        pieces.append(
            f'<span class="confetti-piece" style="left:{left}vw; width:{size}px; height:{size*0.6}px; '
            f'background:{color}; border-radius:{shape}; '
            f'animation-duration:{duration}s; animation-delay:{delay}s; '
            f'--drift:{drift}px; --spin:{spin}deg;"></span>'
        )
